import { test, expect } from "@playwright/test";

/**
 * Regression test for SHA f9c9d83d — Pagefind search engine must return
 * results for a known-good query.
 *
 * The site uses Pagefind (WebAssembly-based full-text search) served
 * behind a CSP that includes 'wasm-unsafe-eval'. If the CSP directive
 * is accidentally removed, or the pagefind index/bundle is missing or
 * stale, these tests catch it before deploy.
 *
 * Tests run against the built dist (astro preview), which includes the
 * real pagefind index generated by `pagefind --site dist`.
 */

const SEARCH_PAGE = "/buscar/";

/**
 * The pagefind UI renders its own internal form inside #pagefind-search.
 * The internal form, input, and clear button are hidden via CSS
 * (display:none) because buscar.astro provides its own custom form.
 * Results and message become visible after a search is triggered.
 *
 * Use `state: "attached"` for hidden pagefind elements, `state: "visible"`
 * for results/messages that appear after search.
 */
const SELECTORS = {
  internalForm: ".pagefind-ui__form",
  internalInput: ".pagefind-ui__search-input",
  message: ".pagefind-ui__message",
  results: ".pagefind-ui__result",
  resultLink: ".pagefind-ui__result-link",
  customInput: "#site-search",
  submitButton: '#search-form button[type="submit"]',
  emptyState: "#search-empty-state",
  clearButton: "#search-clear-button",
  region: "#pagefind-search",
} as const;

const NO_MATCH_QUERY = "zzzqqqxyz-abracadabra";

test.describe("Search — Pagefind functional regression", () => {
  test("search form initializes Pagefind UI on load", async ({ page }) => {
    await page.goto(SEARCH_PAGE);
    await page.waitForLoadState("networkidle");
    // Pagefind UI renders asynchronously inside requestIdleCallback.
    // The internal form is hidden via CSS but must exist in DOM.
    await page.waitForSelector(SELECTORS.internalForm, {
      state: "attached",
      timeout: 10000,
    });

    await expect(page.locator(SELECTORS.internalForm)).toBeAttached();
    await expect(page.locator(SELECTORS.internalInput)).toBeAttached();
  });

  test("returns results for a single-word query", async ({ page }) => {
    await page.goto(SEARCH_PAGE);
    await page.waitForLoadState("networkidle");
    await page.waitForSelector(SELECTORS.internalForm, {
      state: "attached",
      timeout: 10000,
    });

    await page.locator(SELECTORS.customInput).fill("sueldo");
    await page.locator(SELECTORS.submitButton).click();

    // Results and message appear after search completes
    await page.waitForSelector(SELECTORS.results, { timeout: 10000 });
    await expect(page.locator(SELECTORS.message)).toBeVisible();

    const messageText = await page.locator(SELECTORS.message).textContent();
    expect(messageText).toMatch(/\d+/);
    expect(messageText).not.toMatch(/No se encontraron resultados/i);

    const resultCount = await page.locator(SELECTORS.results).count();
    expect(resultCount).toBeGreaterThan(0);
  });

  test("returns results for a multi-word query with accented characters", async ({
    page,
  }) => {
    await page.goto(SEARCH_PAGE);
    await page.waitForLoadState("networkidle");
    await page.waitForSelector(SELECTORS.internalForm, {
      state: "attached",
      timeout: 10000,
    });

    await page.locator(SELECTORS.customInput).fill("sueldo líquido");
    await page.locator(SELECTORS.submitButton).click();

    await page.waitForSelector(SELECTORS.results, { timeout: 10000 });
    await expect(page.locator(SELECTORS.message)).toBeVisible();

    const messageText = await page.locator(SELECTORS.message).textContent();
    expect(messageText).toMatch(/\d+/);
    expect(messageText).not.toMatch(/No se encontraron resultados/i);

    const resultCount = await page.locator(SELECTORS.results).count();
    expect(resultCount).toBeGreaterThan(0);
  });

  test("results link to actual site pages", async ({ page }) => {
    await page.goto(SEARCH_PAGE);
    await page.waitForLoadState("networkidle");
    await page.waitForSelector(SELECTORS.internalForm, {
      state: "attached",
      timeout: 10000,
    });

    await page.locator(SELECTORS.customInput).fill("sueldo");
    await page.locator(SELECTORS.submitButton).click();

    await page.waitForSelector(SELECTORS.results, { timeout: 10000 });

    const firstResult = page.locator(SELECTORS.resultLink).first();
    await expect(firstResult).toBeVisible();

    const href = await firstResult.getAttribute("href");
    expect(href).toBeTruthy();
    expect(href).toMatch(/^\//);
  });

  test("debounced input triggers search without explicit submit", async ({
    page,
  }) => {
    await page.goto(SEARCH_PAGE);
    await page.waitForLoadState("networkidle");
    await page.waitForSelector(SELECTORS.internalForm, {
      state: "attached",
      timeout: 10000,
    });

    // Typing triggers debounced search after 300ms — no click needed
    await page.locator(SELECTORS.customInput).fill("afp");

    await page.waitForSelector(SELECTORS.results, { timeout: 10000 });
    await expect(page.locator(SELECTORS.message)).toBeVisible();

    const messageText = await page.locator(SELECTORS.message).textContent();
    expect(messageText).toMatch(/\d+/);
    expect(messageText).not.toMatch(/No se encontraron resultados/i);
  });

  test("clearing input resets to empty state", async ({ page }) => {
    await page.goto(SEARCH_PAGE);
    await page.waitForLoadState("networkidle");
    await page.waitForSelector(SELECTORS.internalForm, {
      state: "attached",
      timeout: 10000,
    });

    const input = page.locator(SELECTORS.customInput);
    await input.fill("sueldo");
    await page.locator(SELECTORS.submitButton).click();
    await page.waitForSelector(SELECTORS.results, { timeout: 10000 });

    // Clear the input — triggers debounced empty search which collapses drawer
    await input.fill("");
    await page.waitForSelector(SELECTORS.results, {
      state: "detached",
      timeout: 5000,
    });

    expect(await page.locator(SELECTORS.results).count()).toBe(0);
  });

  test("search via URL query parameter (?q=) works on page load", async ({
    page,
  }) => {
    await page.goto(`${SEARCH_PAGE}?q=sueldo`);
    await page.waitForLoadState("networkidle");
    await page.waitForSelector(SELECTORS.internalForm, {
      state: "attached",
      timeout: 10000,
    });

    // q param triggers search on page load — results appear without user input
    await page.waitForSelector(SELECTORS.results, { timeout: 10000 });
    await expect(page.locator(SELECTORS.message)).toBeVisible();

    const messageText = await page.locator(SELECTORS.message).textContent();
    expect(messageText).toMatch(/\d+/);
    expect(messageText).not.toMatch(/No se encontraron resultados/i);

    const resultCount = await page.locator(SELECTORS.results).count();
    expect(resultCount).toBeGreaterThan(0);

    // The custom input should be pre-filled with the query
    const inputValue = await page.locator(SELECTORS.customInput).inputValue();
    expect(inputValue).toBe("sueldo");
  });
});

test.describe("Search — zero results, status and recovery (Plan 114)", () => {
  test("a query with no matches shows a terminal empty state with recovery", async ({
    page,
  }) => {
    await page.goto(`${SEARCH_PAGE}?q=${NO_MATCH_QUERY}`);
    await page.waitForLoadState("networkidle");
    await page.waitForSelector(SELECTORS.internalForm, {
      state: "attached",
      timeout: 10000,
    });

    const emptyState = page.locator(SELECTORS.emptyState);
    await expect(emptyState).toBeVisible();
    await expect(emptyState).toContainText("No encontramos resultados");
    await expect(
      emptyState.locator(SELECTORS.clearButton)
    ).toBeVisible();

    // The Pagefind message is announced to assistive technology.
    const message = page.locator(SELECTORS.message);
    await expect(message).toHaveAttribute("role", "status");
    await expect(message).toHaveAttribute("aria-live", "polite");
    await expect(message).toContainText("No se encontraron resultados");
  });

  test("the empty state clear action resets the query and hides the state", async ({
    page,
  }) => {
    await page.goto(`${SEARCH_PAGE}?q=${NO_MATCH_QUERY}`);
    await page.waitForLoadState("networkidle");
    await page.waitForSelector(SELECTORS.internalForm, {
      state: "attached",
      timeout: 10000,
    });
    await expect(page.locator(SELECTORS.emptyState)).toBeVisible();

    await page.locator(SELECTORS.clearButton).click();
    await expect(page.locator(SELECTORS.emptyState)).toBeHidden();
    await expect(page.locator(SELECTORS.customInput)).toHaveValue("");
  });

  test("a query with results keeps the empty state hidden and clears aria-busy", async ({
    page,
  }) => {
    await page.goto(`${SEARCH_PAGE}?q=sueldo`);
    await page.waitForLoadState("networkidle");
    await page.waitForSelector(SELECTORS.internalForm, {
      state: "attached",
      timeout: 10000,
    });
    await page.waitForSelector(SELECTORS.results, { timeout: 10000 });
    await page.waitForFunction(
      () =>
        document.querySelectorAll("#pagefind-search .pagefind-ui__loading")
          .length === 0
    );

    await expect(page.locator(SELECTORS.emptyState)).toBeHidden();
    await expect(page.locator(SELECTORS.message)).toContainText("resultados");
    await expect(page.locator(SELECTORS.region)).not.toHaveAttribute(
      "aria-busy",
      "true"
    );
  });
});
